  position: absolute;
  inset: 0;
  width: 550px !important;
  height: 450px !important;
  pointer-events: none;
}
.main-menu[data-assets='swf']:after {
  display: none;
}
.main-menu[data-assets='swf'] .menu-orb {
  background: transparent;
  box-shadow: none;
}
.main-menu-overlay {
  display: contents;
}
.main-menu-overlay[data-menu-busy='true'] button:disabled {
  opacity: 1;
  cursor: pointer;
}
.main-menu-overlay .modal-scrim:has(.settings-screen),
.main-menu-overlay .modal-scrim:has(.credits-screen) {
  background: transparent;
  backdrop-filter: none;
}
.credits-content,
.credits-art,
.credits-art canvas {
  position: absolute;
  inset: 0;
  width: 550px !important;
  height: 450px !important;
}
.credits-art {
  pointer-events: none;
}
.credits-control {
  position: absolute;
  padding: 0;
  background: transparent !important;
  border: 0;
}
.credits-link-status {
  position: absolute;
  left: 95px;
  right: 95px;
  bottom: 9px;
  margin: 0;
  text-align: center;
  font:
    9px/1.3 Arial,
    sans-serif;
  color: white;
}
.recreation-details {
  width: min(880px, 96vw);
  margin: 12px auto;
  color: #9bc3d1;
  font:
    12px/1.5 Arial,
    sans-serif;
}
.recreation-details summary {
  cursor: pointer;
}
.menu-title {
  position: absolute;
  z-index: 1;
  top: 58px;
  left: 25px;
  width: 500px;
  white-space: nowrap;
}
.menu-title .mock-lettering {
  font-size: 57px !important;
  letter-spacing: -3.3px;
  text-align: center;
}
.menu-orb {
  position: absolute;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #a2d8e933;
  border-radius: 50%;
  box-shadow: inset 0 0 7px #c9fdff08;
  color: #fff;
}
.menu-orb:hover,
.menu-orb:focus-visible {
  background: #c9faff50;
  box-shadow:
    0 0 14px #c9faff33,
    inset 0 0 12px #d1fbff22;
}
.menu-play {
  left: 207px;
  top: 174px;
  width: 136px;
  height: 104px;
  background: radial-gradient(ellipse at 45% 50%, #b6e6ed88, #8bd6e655 60%, #9cecff33);
  box-shadow:
    0 0 13px #d8ffff33,
    inset 0 0 14px #e5ffff11;
}
.menu-play svg {
  filter: drop-shadow(0 0 4px #fff9);
  margin-left: 8px;
}
.menu-create {
  left: 366px;
  top: 229px;
  width: 40px;
  height: 31px;
}
.menu-create svg {
  display: block;
}
.swf-download-guide {
  font-size: 10px !important;
  line-height: 1.45 !important;
  margin: 10px 0 0 !important;
  color: #a3d3de;
}
.swf-download-guide a {
  color: #e7fbff;
  text-decoration: underline;
}
.menu-library {
  left: 146px;
  top: 229px;
  width: 42px;
  height: 32px;
}
.menu-settings {
  left: 184px;
  top: 284px;
  width: 40px;
  height: 31px;
}
.menu-credits {
  left: 327px;
  top: 284px;
  width: 40px;
  height: 31px;
}
.menu-assets {
  left: 255px;
  top: 303px;
  width: 40px;
  height: 31px;
}
